import{_ as c,r as t,o as l,c as i,e as p,a as n,s as u,d as a}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Создание Twig-тегов - October CMS - 3.x","titleTemplate":false,"description":"Расширение Twig пользовательскими фильтрами и функциями.","frontmatter":{"subtitle":"Расширение Twig пользовательскими фильтрами и функциями."},"headers":[{"level":2,"title":"Регистрация фильтра","slug":"регистрация-фильтра","link":"#регистрация-фильтра","children":[]},{"level":2,"title":"Регистрация функции","slug":"регистрация-функции","link":"#регистрация-функции","children":[]},{"level":2,"title":"Экранирование вывода","slug":"экранирование-вывода","link":"#экранирование-вывода","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/twig-tags.md","filePath":"3.x/ru/extend/twig-tags.md"}'),r={name:"3.x/ru/extend/twig-tags.md"};function k(g,s,d,h,m,f){const e=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[p(e),s[0]||(s[0]=n("h1",null,"Создание Twig-тегов",-1)),p(o),s[1]||(s[1]=u(`<p>Пользовательские фильтры и функции Twig могут быть зарегистрированы в CMS с помощью метода <code>registerMarkupTags</code> <a href="./../extend/extending.html">класса регистрации плагина</a>. В этой статье описывается, как регистрировать собственные фильтры и функции Twig, которые можно использовать в CMS и почтовых шаблонах.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMarkupTags</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;filters&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token comment">// ...Filters defined here</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;functions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token comment">// ...Functions defined here</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="регистрация-фильтра"><a href="#регистрация-фильтра" class="header-anchor">#</a> Регистрация фильтра</h2><p>Ключ <code>filters</code> в массиве регистрации может использоваться для Twig-фильтров. Например, фильтр <code>|plural</code> может быть сопоставлен с глобальной PHP-функцией <code>str_plural()</code> следующим значением.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;filters&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;plural&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;str_plural&#39;</span>
<span class="token punctuation">]</span>
</code></pre></div><p>Вы также можете передать локальный метод. Например, <code>|uppercase</code> может быть сопоставлен с методом <code>$this-&gt;makeAllCaps()</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;filters&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;uppercase&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;makeTextAllCaps&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span>
</code></pre></div><p>Это становится доступным в Twig следующим образом.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>my text<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>uppercase <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="регистрация-функции"><a href="#регистрация-функции" class="header-anchor">#</a> Регистрация функции</h2><p>Как и фильтры, ключ <code>functions</code> может использоваться для создания Twig-функции. Например, функция может быть сопоставлена с вызовом статического метода <code>Form::open()</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;functions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;form_open&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;open&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span>
</code></pre></div><p>Статические вызовы также поддерживают определения с подстановочными знаками. В этом примере вызов функции <code>url_foobar()</code> будет преобразован в вызов метода <code>Url::foobar</code> и так далее.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;functions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;url_*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Url</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span>
</code></pre></div><p>Также допускается передача замыкания для любого определения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;functions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;hello_world&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World!&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">]</span>
</code></pre></div><p>Это теперь доступно в Twig следующим образом.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello_world<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="экранирование-вывода"><a href="#экранирование-вывода" class="header-anchor">#</a> Экранирование вывода</h2><p>Важно отметить, что пользовательские фильтры и функции Twig по умолчанию не экранируются. Для включения экранирования по умолчанию передайте последнее значение массива как <code>true</code> в определении.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMarkupTags</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;functions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token comment">// Escaped Functions</span>
            <span class="token string single-quoted-string">&#39;input&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;input&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

            <span class="token comment">// Raw Functions</span>
            <span class="token string single-quoted-string">&#39;link_to&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;link_to&#39;</span><span class="token punctuation">,</span>

            <span class="token comment">// Escaped Classes</span>
            <span class="token string single-quoted-string">&#39;str_*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Str</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

            <span class="token comment">// Raw Classes</span>
            <span class="token string single-quoted-string">&#39;url_*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Url</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;filters&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token comment">// Escaped Filters</span>
            <span class="token string single-quoted-string">&#39;display_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token keyword">fn</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">getDisplayName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

            <span class="token comment">// Raw Filters</span>
            <span class="token string single-quoted-string">&#39;avatar_url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token keyword">fn</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">getAvatarUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

            <span class="token comment">// Escaped Classes</span>
            <span class="token string single-quoted-string">&#39;str_*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Str</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

            <span class="token comment">// Raw Classes</span>
            <span class="token string single-quoted-string">&#39;url_*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Url</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4>`,22)),s[2]||(s[2]=n("div",{class:"custom-block also"},[n("ul",null,[n("li",null,[n("a",{href:"https://twig.symfony.com/doc/3.x/advanced.html",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Расширение Twig"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const _=c(r,[["render",k]]);export{v as __pageData,_ as default};
